def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    gaps = {}
    for r, row in enumerate(grid):
        for c in range(1, w - 1):
            color = row[c - 1]
            if color != 0 and row[c] == 0 and row[c + 1] == color:
                gaps.setdefault(c, []).append((r, color))
    for c, events in gaps.items():
        previous = -1
        for r, color in events:
            for rr in range(previous + 1, r + 1):
                out[rr][c] = color
            previous = r
        if grid[-1][c] != 0:
            bottom = h - 1
            while bottom > 0 and grid[bottom - 1][c] == grid[-1][c]:
                bottom -= 1
            for rr in range(previous + 1, bottom):
                out[rr][c] = grid[-1][c]
    return out
